// Utility
function gTags(s){const t=[];const aw=(s.fw+s.rw)/2;const at=(s.fl+s.fr+s.rl+s.rr)/4;if(aw>=35)t.push({label:"고다운포스",color:"#7c3aed"});else if(aw>=20)t.push({label:"밸런스",color:"#0891b2"});else t.push({label:"저드래그",color:"#dc2626"});if(s.doff<=20)t.push({label:"날카로운 회전",color:"#ea580c"});else if(s.doff>=40)t.push({label:"리어 안정",color:"#16a34a"});if(s.fs>=38)t.push({label:"단단한 프론트",color:"#ca8a04"});if(s.rs<=3)t.push({label:"소프트 리어",color:"#0284c7"});if(at<=22)t.push({label:"저압 그립",color:"#9333ea"});else if(at>=27)t.push({label:"고압 절약",color:"#15803d"});if(s.bb>=56)t.push({label:"프론트 제동",color:"#b45309"});return t;}
function gCS(s,ti){if(!ti)return null;let sc=70;const aw=(s.fw+s.rw)/2;const at=(s.fl+s.fr+s.rl+s.rr)/4;const ld=ti.drag<0.013;const hw=aw>=30;if(ld&&!hw)sc+=10;if(ld&&hw)sc-=8;if(!ld&&hw)sc+=5;if(ti.aeroF>=3.3&&s.fw<=15)sc+=8;if(ti.aeroF<2.9&&s.fw<=10)sc-=10;if(ti.aeroR>=2.0&&s.doff<=25)sc+=8;if(ti.aeroR<1.85&&s.doff<=20)sc-=8;if(ti.mass>=810&&s.fs>=38)sc+=5;if(ti.mass<=800&&s.fs<=30)sc+=5;if(ti.wDist>=0.2&&s.bb<=54)sc+=7;if(ti.wDist<=0.17&&s.bb>=56)sc+=5;if(ti.wDist>=0.2&&s.bb>=57)sc-=7;if(ti.gear>=1.67&&s.don>=100)sc+=5;if(ti.gear<1.55&&s.don>=100)sc-=5;if(ti.mass>=810&&at<=24)sc+=5;if(ti.mass<=800&&at>=28)sc+=3;return Math.max(0,Math.min(100,Math.round(sc)));}
function gCL(sc){if(sc>=88)return{label:"완벽한 궁합",color:"#22c55e",icon:"⭐"};if(sc>=76)return{label:"좋은 궁합",color:"#84cc16",icon:"✅"};if(sc>=63)return{label:"보통 궁합",color:"#eab308",icon:"⚠️"};if(sc>=50)return{label:"아쉬운 궁합",color:"#f97316",icon:"🔶"};return{label:"낮은 궁합",color:"#ef4444",icon:"❌"};}
function gFeel(s){const aw=(s.fw+s.rw)/2;const at=(s.fl+s.fr+s.rl+s.rr)/4;const f=[];if(aw>=40)f.push("윙 최대");else if(aw>=25)f.push("윙 중상");else if(aw>=10)f.push("윙 낮음");else f.push("윙 최소");if(s.doff<=20)f.push("진입 날카로움");else if(s.doff>=40)f.push("리어 안정형");if(s.rs<=3)f.push("리어 트랙션↑");if(s.fs>=38)f.push("프론트 반응↑");if(at<=22)f.push("저압 그립↑");else if(at>=27)f.push("고압 마모↓");return f.join(" · ");}

async function callClaude(messages, systemPrompt, signal, key?) {
  const k = key || ENV_KEY;
  if (!k) throw new Error("API 키를 설정해주세요");
  const res = await fetch(API_URL, { method: "POST", headers: { "Content-Type": "application/json", "x-api-key": k, "anthropic-version": "2023-06-01", "anthropic-dangerous-direct-browser-access": "true" }, body: JSON.stringify({ model: "claude-sonnet-4-20250514", max_tokens: 1024, system: systemPrompt || undefined, messages }), signal });
  if (!res.ok) throw new Error(`API ${res.status}`);
  const data = await res.json();
  return data.content?.filter(b => b.type === "text").map(b => b.text).join("\n") || "";
}

const C={bg:"#0a0e1a",card:"#111827",card2:"#1a2235",border:"rgba(255,255,255,0.08)",border2:"rgba(255,255,255,0.15)",text:"#f1f5f9",muted:"#94a3b8",dim:"#475569",red:"#ef4444"};
function Bar({v,min,max}){const p=Math.max(0,Math.min(100,((v-min)/(max-min))*100));const c=p<33?"#3b82f6":p<66?"#eab308":"#ef4444";return(<div style={{background:"rgba(255,255,255,0.07)",borderRadius:3,height:4,overflow:"hidden"}}><div style={{width:`${p}%`,height:"100%",background:c,borderRadius:3}}/></div>);}
function RC({s1,s2,m1,m2,size=260}){const cx=size/2,cy=size/2,r=size/2-40,n=RK.length;const nm=(k,v)=>{const d=DEFS[k];return(v-d.min)/(d.max-d.min);};const pt=(i,v)=>{const a=(Math.PI*2*i/n)-Math.PI/2;return{x:cx+r*v*Math.cos(a),y:cy+r*v*Math.sin(a)};};const p1=RK.map((k,i)=>pt(i,nm(k.k,s1[k.k])));const p2=s2?RK.map((k,i)=>pt(i,nm(k.k,s2[k.k]))):null;const po=pts=>pts.map(p=>`${p.x},${p.y}`).join(" ");return(<svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>{[0.25,0.5,0.75,1].map(lv=><polygon key={lv} points={po(RK.map((_,i)=>pt(i,lv)))} fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth={1}/>)}{RK.map((_,i)=>{const p=pt(i,1);return<line key={i} x1={cx} y1={cy} x2={p.x} y2={p.y} stroke="rgba(255,255,255,0.06)" strokeWidth={1}/>;})}<polygon points={po(p1)} fill={`${m1?.color||"#a855f7"}25`} stroke={m1?.color||"#a855f7"} strokeWidth={2}/>{p1.map((p,i)=><circle key={i} cx={p.x} cy={p.y} r={3} fill={m1?.color||"#a855f7"}/>)}{p2&&<><polygon points={po(p2)} fill={`${m2?.color||"#eab308"}25`} stroke={m2?.color||"#eab308"} strokeWidth={2} strokeDasharray="6,3"/>{p2.map((p,i)=><circle key={i} cx={p.x} cy={p.y} r={3} fill={m2?.color||"#eab308"}/>)}</>}{RK.map((k,i)=>{const p=pt(i,1.15);return<text key={i} x={p.x} y={p.y} textAnchor="middle" dominantBaseline="middle" fill="#94a3b8" fontSize={9} fontWeight={600}>{k.l}</text>;})}</svg>);}

// ============================================================
// MAIN COMPONENT — Full 6-tab version
// ============================================================
export function F1SetupManager() {
  const [tab,setTab]=useState("main");
  const [apiKey,setApiKey]=useState(()=>{try{return localStorage.getItem('frc_api_key')||ENV_KEY||'';}catch{return'';}});
  // Main tab
  const [step,setStep]=useState(1);
  const [track,setTrack]=useState(null);
  const [mode,setMode]=useState(null);
  const [weather,setWeather]=useState(null);
  const [team,setTeam]=useState(null);
  const [selSetup,setSelSetup]=useState(null);
  const [selMeta,setSelMeta]=useState(null);
  const [expanded,setExpanded]=useState({});
  const [fg,setFg]=useState("all");
  const [chat,setChat]=useState([]);const [input,setInput]=useState("");const [loading,setLoading]=useState(false);const [chatHist,setChatHist]=useState([]);
  // Teams tab
  const [te,setTe]=useState(null);
  // Compare tab
  const [cmpT,setCmpT]=useState(null);const [cmpA,setCmpA]=useState(null);const [cmpB,setCmpB]=useState(null);const [cmpW,setCmpW]=useState("dry");
  // Ask tab
  const [askQ,setAskQ]=useState("");const [askChat,setAskChat]=useState([]);const [askLoad,setAskLoad]=useState(false);const [askHist,setAskHist]=useState([]);
  // MySetup tab
  const [myTrack,setMyTrack]=useState(null);const [myMode,setMyMode]=useState(null);const [myTeam,setMyTeam]=useState(null);
  const [myVals,setMyVals]=useState(()=>{const iv={};FIELDS.forEach(f=>{const d=DEFS[f.k];iv[f.k]=Math.round(((d.min+d.max)/2)*10)/10;});return iv;});
  const [myChat,setMyChat]=useState([]);const [myInput,setMyInput]=useState("");const [myLoad,setMyLoad]=useState(false);const [myHist,setMyHist]=useState([]);
  const chatEnd=useRef(null);const askRef=useRef(null);const myEnd=useRef(null);

  useEffect(()=>{chatEnd.current?.scrollIntoView({behavior:"smooth"});},[chat]);
  useEffect(()=>{askRef.current?.scrollIntoView({behavior:"smooth"});},[askChat]);
  useEffect(()=>{myEnd.current?.scrollIntoView({behavior:"smooth"});},[myChat]);

  const dd=track?DB[track]:null;
  const ti=TEAMS.find(t=>t.name===team);
  const isNE=mode==="nonequal";
  const ts=isNE?6:5;

  const sTrack=t=>{setTrack(t);setMode(null);setWeather(null);setTeam(null);setSelSetup(null);setSelMeta(null);setChat([]);setChatHist([]);setStep(2);};
  const sMode=m=>{setMode(m);setWeather(null);setTeam(null);setSelSetup(null);setSelMeta(null);setChat([]);setChatHist([]);setStep(m==="nonequal"?2.5:3);};
  const sTeam=t=>{setTeam(t);setWeather(null);setSelSetup(null);setSelMeta(null);setChat([]);setChatHist([]);setStep(3);};
  const sW=w=>{setWeather(w);setSelSetup(null);setSelMeta(null);setChat([]);setChatHist([]);setFg("all");setStep(4);};
  const sSt=(m,s)=>{setSelMeta(m);setSelSetup(s);setChat([]);setChatHist([]);setLoading(false);setStep(5);};

  const bSys=()=>{if(!selSetup)return"";const sw=FIELDS.map(f=>`${DEFS[f.k].name}:${selSetup[f.k]}(${DEFS[f.k].min}~${DEFS[f.k].max})`).join("\n");const ti2=dd?.track?`\n[트랙]${track}|${dd.track.notes}\nS:${dd.track.softLife} M:${dd.track.medLife} H:${dd.track.hardLife}\n전략:${dd.track.strategy}`:"";const tw=ti?`\n[차량]${ti.name} 장점:${ti.pros} 단점:${ti.cons}`:"";return`F1 25 셋업 엔지니어. 피드백→셋업 변경.\n\n${KNOWLEDGE_BASE}\n\n[환경]${track}|${isNE?"논이퀄":"이퀄"}|${weather==="rain"?"우천":"건조"}|${selMeta?.label}${ti2}${tw}\n[셋업]\n${sw}\n[규칙]1.공감+해석 2."항목 현재→추천" 3.이유1줄 4.한국어3~5줄 5.2~3개변경`;};

  const send=async()=>{if(!input.trim()||loading)return;const m=input.trim();setInput("");setChat(p=>[...p,{r:"u",t:m}]);const nh=[...chatHist,{role:"user",content:m}];setLoading(true);try{const ctrl=new AbortController();const tid=setTimeout(()=>ctrl.abort(),30000);const txt=await callClaude(nh,bSys(),ctrl.signal,apiKey);clearTimeout(tid);setChat(p=>[...p,{r:"a",t:txt}]);setChatHist([...nh,{role:"assistant",content:txt}]);}catch(e){setChat(p=>[...p,{r:"a",t:e.name==="AbortError"?"⚠️ 타임아웃":"⚠️ "+e.message}]);}setLoading(false);};

  const askSend=async()=>{if(!askQ.trim()||askLoad)return;const m=askQ.trim();setAskQ("");setAskChat(p=>[...p,{r:"u",t:m}]);const sys=`F1 25 셋업 전문가. 한국어 3~8줄 답변.\n\n${KNOWLEDGE_BASE}`;const nh=[...askHist,{role:"user",content:m}];setAskLoad(true);try{const ctrl=new AbortController();const tid=setTimeout(()=>ctrl.abort(),30000);const txt=await callClaude(nh,sys,ctrl.signal,apiKey);clearTimeout(tid);setAskChat(p=>[...p,{r:"a",t:txt}]);setAskHist([...nh,{role:"assistant",content:txt}]);}catch(e){setAskChat(p=>[...p,{r:"a",t:"⚠️ "+e.message}]);}setAskLoad(false);};

  const mySend=async()=>{if(!myInput.trim()||myLoad||!myTrack)return;const m=myInput.trim();setMyInput("");setMyChat(p=>[...p,{r:"u",t:m}]);const sw=FIELDS.map(f=>`${DEFS[f.k].name}:${myVals[f.k]}`).join("\n");const myTi=TEAMS.find(t=>t.name===myTeam);const myDD=DB[myTrack];const ti2=myDD?.track?`\n[트랙]${myTrack}|${myDD.track.notes}`:"";const tw=myTi?`\n[차량]${myTi.name} 장점:${myTi.pros} 단점:${myTi.cons}`:"";const sys=`F1 25 셋업 엔지니어. 사용자 커스텀 셋업 분석.\n\n${KNOWLEDGE_BASE}\n\n[환경]${myTrack}${ti2}${tw}\n[사용자 셋업]\n${sw}\n[규칙]한국어3~5줄, 2~3개변경 추천`;const nh=[...myHist,{role:"user",content:m}];setMyLoad(true);try{const ctrl=new AbortController();const tid=setTimeout(()=>ctrl.abort(),30000);const txt=await callClaude(nh,sys,ctrl.signal,apiKey);clearTimeout(tid);setMyChat(p=>[...p,{r:"a",t:txt}]);setMyHist([...nh,{role:"assistant",content:txt}]);}catch(e){setMyChat(p=>[...p,{r:"a",t:"⚠️ "+e.message}]);}setMyLoad(false);};

  const fM=SM.filter(m=>{const wO=weather==="rain"?m.rain:!m.rain;const gO=fg==="all"||m.group===fg;return wO&&gO;});
  const sortM=isNE&&ti?[...fM].sort((a,b)=>{const sa=dd?.[getDbKey(a)];const sb=dd?.[getDbKey(b)];if(!sa||!sb)return 0;return(gCS(sb,ti)||0)-(gCS(sa,ti)||0);}):fM;
  const cD=cmpT?DB[cmpT]:null;const cSA=cmpA&&cD?cD[getDbKey(SM.find(m=>m.key===cmpA)||{key:cmpA})]:null;const cSB=cmpB&&cD?cD[getDbKey(SM.find(m=>m.key===cmpB)||{key:cmpB})]:null;const cMA=SM.find(m=>m.key===cmpA);const cMB=SM.find(m=>m.key===cmpB);
  const qQ=weather==="rain"?["비에서 스핀","비에서 안꺾임","웻 브레이킹 불안"]:["리어 미끄러움","언더스티어","탑스피드 낮음","앞바퀴 잠김","타이어 과열","코너 탈출 느림"];
  const TABS=[["main","🔧 셋업"],["teams","🏁 차량"],["compare","📊 비교"],["mysetup","🔍 내 셋업"],["ask","❓ 질문"]];
  const SH=({n,title,done})=>(<div style={{display:"flex",alignItems:"center",gap:10,marginBottom:12}}><div style={{width:26,height:26,borderRadius:"50%",display:"flex",alignItems:"center",justifyContent:"center",fontSize:12,fontWeight:600,flexShrink:0,background:done?"#22c55e":n===Math.floor(step)||n===step?"#ef4444":"rgba(255,255,255,0.08)",color:done||n===Math.floor(step)||n===step?"#fff":C.dim}}>{done?"✓":n}</div><div><div style={{fontSize:13,fontWeight:600,color:n===Math.floor(step)||n===step?C.text:C.dim}}>{title}</div><div style={{fontSize:10,color:C.dim}}>Step {n}/{ts}</div></div></div>);

  return (
    <div style={{minHeight:"100vh",background:C.bg,color:C.text,fontFamily:"system-ui,sans-serif",fontSize:13}}>
      <div style={{background:"#0d1220",borderBottom:"1px solid rgba(255,255,255,0.15)",padding:"13px 16px",display:"flex",alignItems:"center",gap:12,WebkitAppRegion:"drag"} as any}>
        <span style={{fontSize:22}}>🏎️</span>
        <div style={{flex:1}}><div style={{fontSize:15,fontWeight:700}}>F1 25 셋업 매니저</div><div style={{fontSize:10,color:C.dim}}>Puki · BL · AI · 2025</div></div>
        {!apiKey&&<button onClick={()=>{const k=prompt("Anthropic API Key:");if(k){setApiKey(k);localStorage.setItem('frc_api_key',k);}}} style={{WebkitAppRegion:"no-drag",padding:"4px 10px",borderRadius:6,border:"1px solid #ef444433",background:"transparent",color:"#f87171",fontSize:10,cursor:"pointer"} as any}>🔑 API Key</button>}
      </div>

      {/* ── Tab Bar ── */}
      <div style={{display:"flex",background:"#0d1220",borderBottom:`1px solid ${C.border}`,overflowX:"auto"}}>
        {TABS.map(([k,l])=>(<button key={k} onClick={()=>setTab(k)} style={{flex:1,padding:"10px 0",border:"none",background:"transparent",color:tab===k?C.text:C.dim,fontSize:11,fontWeight:tab===k?600:400,cursor:"pointer",borderBottom:tab===k?`2px solid ${C.red}`:"2px solid transparent",whiteSpace:"nowrap",minWidth:60}}>{l}</button>))}
      </div>

      <div style={{padding:"14px 14px 80px"}}>

        {/* ── 차량 탭 ── */}
        {tab==="teams"&&(<div>{TEAMS.sort((a,b)=>b.total-a.total).map((t,i)=>(<div key={t.name} onClick={()=>setTe(te===t.name?null:t.name)} style={{background:C.card,borderRadius:10,padding:"12px 14px",marginBottom:8,cursor:"pointer",border:`1px solid ${te===t.name?C.red:C.border}`}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}><div style={{display:"flex",alignItems:"center",gap:10}}><span style={{fontSize:14,fontWeight:700,color:i===0?"#fbbf24":C.dim,minWidth:20}}>{i+1}</span><span style={{fontWeight:600}}>{t.name}</span></div><div style={{display:"flex",alignItems:"center",gap:8}}><span style={{fontSize:15,fontWeight:700,color:C.red}}>{t.total}</span><span style={{fontSize:10,color:C.dim}}>{te===t.name?"▲":"▼"}</span></div></div>{te===t.name&&(<div style={{marginTop:12,display:"grid",gridTemplateColumns:"1fr 1fr",gap:6}}><div style={{background:"rgba(34,197,94,0.08)",borderRadius:6,padding:"8px 10px"}}><p style={{fontSize:9,color:"#4ade80",fontWeight:600,margin:"0 0 3px"}}>장점</p><p style={{fontSize:10,color:"#86efac",margin:0,lineHeight:1.5}}>{t.pros}</p></div><div style={{background:"rgba(239,68,68,0.08)",borderRadius:6,padding:"8px 10px"}}><p style={{fontSize:9,color:"#f87171",fontWeight:600,margin:"0 0 3px"}}>단점</p><p style={{fontSize:10,color:"#fca5a5",margin:0,lineHeight:1.5}}>{t.cons}</p></div></div>)}</div>))}</div>)}

        {/* ── 비교 탭 ── */}
        {tab==="compare"&&(<div style={{display:"flex",flexDirection:"column",gap:12}}>
          <div style={{background:C.card,borderRadius:12,padding:14,border:`1px solid ${C.border}`}}>
            <div style={{fontSize:14,fontWeight:700,marginBottom:10}}>📊 셋업 비교</div>
            <div style={{marginBottom:12}}><div style={{fontSize:11,fontWeight:600,color:C.muted,marginBottom:6}}>트랙</div><div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:4}}>{TD.map(t=>(<button key={t.name} onClick={()=>{setCmpT(t.name);setCmpA(null);setCmpB(null);}} style={{padding:"6px 4px",borderRadius:6,border:`1px solid ${cmpT===t.name?C.red:C.border}`,background:cmpT===t.name?"rgba(239,68,68,0.12)":C.card2,color:cmpT===t.name?C.red:C.text,fontSize:10,cursor:"pointer"}}>{t.name}</button>))}</div></div>
            {cmpT&&cD&&(<div style={{display:"flex",flexDirection:"column",gap:10}}>
              <div style={{display:"flex",gap:6}}>{[["dry","☀️ 건조"],["rain","🌧️ 우천"]].map(([k,l])=>(<button key={k} onClick={()=>{setCmpW(k);setCmpA(null);setCmpB(null);}} style={{padding:"5px 12px",borderRadius:20,border:`1px solid ${cmpW===k?C.red:C.border}`,background:cmpW===k?C.red:"transparent",color:cmpW===k?"#fff":C.muted,fontSize:11,cursor:"pointer"}}>{l}</button>))}</div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>{[["A",cmpA,setCmpA,"#a855f7"],["B",cmpB,setCmpB,"#eab308"]].map(([label,val,setVal,col])=>(<div key={label}><div style={{fontSize:11,fontWeight:600,color:col,marginBottom:6}}>셋업 {label}</div><div style={{display:"flex",flexDirection:"column",gap:3}}>{SM.filter(m=>cmpW==="rain"?m.rain:!m.rain).map(m=>{if(!cD[getDbKey(m)])return null;return(<button key={m.key} onClick={()=>setVal(m.key)} style={{padding:"5px 8px",borderRadius:6,border:`1px solid ${val===m.key?col:C.border}`,background:val===m.key?`${col}18`:C.card2,color:val===m.key?col:C.muted,fontSize:10,cursor:"pointer",textAlign:"left"}}>{m.label}</button>);})}</div></div>))}</div>
            </div>)}
          </div>
          {cSA&&cSB&&(<div style={{display:"flex",flexDirection:"column",gap:12}}>
            <div style={{background:C.card,borderRadius:12,padding:14,border:`1px solid ${C.border}`,display:"flex",flexDirection:"column",alignItems:"center"}}><div style={{display:"flex",gap:16,marginBottom:8,fontSize:11}}><span style={{color:cMA?.color}}>● {cMA?.label}</span><span style={{color:cMB?.color}}>◆ {cMB?.label}</span></div><RC s1={cSA} s2={cSB} m1={cMA} m2={cMB}/></div>
            <div style={{background:C.card,borderRadius:12,padding:14,border:`1px solid ${C.border}`}}><div style={{fontSize:12,fontWeight:700,marginBottom:10}}>항목별 비교</div>{FIELDS.map(f=>{const va=cSA[f.k],vb=cSB[f.k],diff=vb-va;const dc=Math.abs(diff)<0.5?"#475569":diff>0?"#22c55e":"#ef4444";return(<div key={f.k} style={{display:"flex",alignItems:"center",gap:8,padding:"5px 8px",background:C.card2,borderRadius:6,marginBottom:4}}><span style={{fontSize:10,color:C.dim,minWidth:90}}>{f.l}</span><span style={{fontSize:11,fontWeight:600,color:cMA?.color,minWidth:40,textAlign:"right"}}>{va}</span><div style={{flex:1,height:4,background:"rgba(255,255,255,0.06)",borderRadius:2}}/><span style={{fontSize:11,fontWeight:600,color:cMB?.color,minWidth:40,textAlign:"right"}}>{vb}</span><span style={{fontSize:10,fontWeight:700,color:dc,minWidth:40,textAlign:"right"}}>{diff>0?"+":""}{diff!==0?diff.toFixed(1):"-"}</span></div>);})}</div>
          </div>)}
        </div>)}

        {/* ── 내 셋업 탭 ── */}
        {tab==="mysetup"&&(<div style={{display:"flex",flexDirection:"column",gap:12}}>
          <div style={{background:C.card,borderRadius:12,border:"1px solid rgba(251,191,36,0.3)",overflow:"hidden"}}>
            <div style={{background:C.card2,padding:"14px 16px",borderBottom:`1px solid ${C.border}`}}><div style={{fontSize:14,fontWeight:700,marginBottom:4}}>🔍 내 셋업 분석</div><p style={{fontSize:11,color:C.muted,margin:0}}>슬라이더로 값을 입력하고 AI 분석을 받으세요.</p></div>
            <div style={{padding:"14px 16px",display:"flex",flexDirection:"column",gap:14}}>
              <div><div style={{fontSize:11,fontWeight:600,color:C.muted,marginBottom:6}}>서킷</div><div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:4}}>{TD.map(t=>(<button key={t.name} onClick={()=>{setMyTrack(t.name);setMyChat([]);setMyHist([]);}} style={{padding:"6px 4px",borderRadius:6,border:`1px solid ${myTrack===t.name?"#fbbf24":C.border}`,background:myTrack===t.name?"rgba(251,191,36,0.12)":C.card2,color:myTrack===t.name?"#fbbf24":C.text,fontSize:10,cursor:"pointer"}}>{t.name}</button>))}</div></div>
              <div><div style={{fontSize:11,fontWeight:600,color:C.muted,marginBottom:8}}>셋업 값</div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"8px 14px"}}>{FIELDS.map(f=>{const d=DEFS[f.k];const v=myVals[f.k];const p=((v-d.min)/(d.max-d.min))*100;const sc=d.min%1!==0||d.max%1!==0?0.5:1;return(<div key={f.k}><div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}><span style={{fontSize:10,color:C.dim}}>{f.l}</span><span style={{fontSize:11,fontWeight:700,color:"#fbbf24"}}>{v}</span></div><input type="range" min={d.min} max={d.max} step={sc} value={v} onChange={e=>setMyVals(pv=>({...pv,[f.k]:parseFloat(e.target.value)}))} style={{width:"100%",height:6,appearance:"none",WebkitAppearance:"none",background:`linear-gradient(to right, #fbbf24 ${p}%, rgba(255,255,255,0.1) ${p}%)`,borderRadius:3,outline:"none",cursor:"pointer"}}/></div>);})}</div></div>
            </div>
          </div>
          {myTrack&&(<div style={{background:C.card,borderRadius:12,border:"1px solid rgba(251,191,36,0.3)",overflow:"hidden"}}>
            <div style={{background:C.card2,padding:"12px 16px",borderBottom:`1px solid ${C.border}`}}><span style={{fontSize:12,fontWeight:600}}>{myTrack}</span></div>
            <div style={{padding:"14px 16px"}}>
              <div style={{minHeight:160,maxHeight:360,overflowY:"auto",display:"flex",flexDirection:"column",gap:8,marginBottom:10}}>
                {myChat.length===0&&<div style={{textAlign:"center",color:C.dim,paddingTop:30,fontSize:11}}>아래 예시를 누르거나 질문하세요</div>}
                {myChat.map((m,i)=>(<div key={i} style={{display:"flex",justifyContent:m.r==="u"?"flex-end":"flex-start"}}><div style={{maxWidth:"86%",padding:"10px 13px",fontSize:12,lineHeight:1.7,borderRadius:m.r==="u"?"12px 12px 3px 12px":"12px 12px 12px 3px",background:m.r==="u"?"#b45309":C.card2,border:m.r==="a"?`1px solid ${C.border}`:"none",color:C.text,whiteSpace:"pre-wrap"}}>{m.t}</div></div>))}
                {myLoad&&<div style={{display:"flex",justifyContent:"flex-start"}}><div style={{padding:"10px 14px",borderRadius:"12px 12px 12px 3px",fontSize:12,color:C.muted,background:C.card2}}>🔍 분석 중…</div></div>}
                <div ref={myEnd}/>
              </div>
              <div style={{display:"flex",flexWrap:"wrap",gap:5,marginBottom:10}}>{["이 셋업 어때?","언더스티어 생길까?","직선 속도는?","타이어 마모 어떨까?"].map(q=>(<button key={q} onClick={()=>setMyInput(q)} style={{fontSize:10,padding:"5px 10px",borderRadius:12,cursor:"pointer",border:"1px solid rgba(251,191,36,0.3)",background:"rgba(251,191,36,0.08)",color:"#fbbf24"}}>{q}</button>))}</div>
              <div style={{display:"flex",gap:7}}><input value={myInput} onChange={e=>setMyInput(e.target.value)} onKeyDown={e=>e.key==="Enter"&&mySend()} placeholder="셋업에 대해 질문하세요…" style={{flex:1,padding:"10px 14px",borderRadius:8,border:"1px solid rgba(251,191,36,0.3)",background:C.card2,color:C.text,fontSize:12,outline:"none"}}/><button onClick={mySend} disabled={myLoad} style={{padding:"10px 18px",borderRadius:8,border:"none",background:myLoad?"#374151":"#b45309",color:"#fff",fontSize:12,fontWeight:700,cursor:myLoad?"not-allowed":"pointer"}}>분석</button></div>
            </div>
          </div>)}
        </div>)}

        {/* ── 질문 탭 ── */}
        {tab==="ask"&&(<div style={{display:"flex",flexDirection:"column",gap:12}}>
          <div style={{background:C.card,borderRadius:12,border:"1px solid rgba(167,139,250,0.3)",overflow:"hidden"}}>
            <div style={{background:C.card2,padding:"14px 16px",borderBottom:`1px solid ${C.border}`}}><div style={{fontSize:14,fontWeight:700,marginBottom:4}}>❓ 셋업 질문</div><p style={{fontSize:11,color:C.muted,margin:0}}>SimRacingSetups + Traxion 가이드 기반 답변</p></div>
            <div style={{padding:"14px 16px"}}>
              <div style={{minHeight:200,maxHeight:400,overflowY:"auto",display:"flex",flexDirection:"column",gap:8,marginBottom:10}}>
                {askChat.length===0&&<div style={{textAlign:"center",color:C.dim,paddingTop:40,fontSize:11}}><div style={{fontSize:28,marginBottom:8}}>🤔</div>아래 예시를 눌러보세요</div>}
                {askChat.map((m,i)=>(<div key={i} style={{display:"flex",justifyContent:m.r==="u"?"flex-end":"flex-start"}}><div style={{maxWidth:"86%",padding:"10px 13px",fontSize:12,lineHeight:1.7,borderRadius:m.r==="u"?"12px 12px 3px 12px":"12px 12px 12px 3px",background:m.r==="u"?"#7c3aed":C.card2,border:m.r==="a"?`1px solid ${C.border}`:"none",color:C.text,whiteSpace:"pre-wrap"}}>{m.t}</div></div>))}
                {askLoad&&<div style={{display:"flex",justifyContent:"flex-start"}}><div style={{padding:"10px 14px",borderRadius:"12px 12px 12px 3px",fontSize:12,color:C.muted,background:C.card2}}>🤔 답변 생성 중…</div></div>}
                <div ref={askRef}/>
              </div>
              <div style={{display:"flex",flexWrap:"wrap",gap:5,marginBottom:10}}>{["프론트 윙 올리면?","오프스로틀 디프가 뭔가요?","브레이크 바이어스?","타이어 압력 높으면?","리어 안티롤바 역할?"].map(q=>(<button key={q} onClick={()=>setAskQ(q)} style={{fontSize:10,padding:"5px 10px",borderRadius:12,cursor:"pointer",border:"1px solid rgba(167,139,250,0.3)",background:"rgba(167,139,250,0.08)",color:"#c4b5fd"}}>{q}</button>))}</div>
              <div style={{display:"flex",gap:7}}><input value={askQ} onChange={e=>setAskQ(e.target.value)} onKeyDown={e=>e.key==="Enter"&&askSend()} placeholder="셋업에 대해 질문하세요…" style={{flex:1,padding:"10px 14px",borderRadius:8,border:"1px solid rgba(167,139,250,0.3)",background:C.card2,color:C.text,fontSize:12,outline:"none"}}/><button onClick={askSend} disabled={askLoad} style={{padding:"10px 18px",borderRadius:8,border:"none",background:askLoad?"#374151":"#7c3aed",color:"#fff",fontSize:12,fontWeight:700,cursor:askLoad?"not-allowed":"pointer"}}>질문</button></div>
            </div>
          </div>
        </div>)}

        {/* ── 메인 셋업 탭 ── */}
        {tab==="main"&&(<div style={{display:"flex",flexDirection:"column",gap:12}}>
          {/* Step 1: Track */}
          <div style={{background:C.card,borderRadius:12,border:`1px solid ${step===1?C.red:C.border}`,overflow:"hidden"}}><div style={{background:C.card2,padding:"12px 14px",borderBottom:`1px solid ${C.border}`}}><SH n={1} title="트랙 선택" done={!!track&&step>1}/></div><div style={{padding:"12px 14px"}}><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:6}}>{TD.map(t=>(<button key={t.name} onClick={()=>sTrack(t.name)} style={{display:"flex",alignItems:"center",gap:8,padding:"9px 11px",borderRadius:8,cursor:"pointer",textAlign:"left",border:`1px solid ${track===t.name?C.red:C.border}`,background:track===t.name?"rgba(239,68,68,0.12)":C.card2}}><FI flag={t.flag} size={20}/><div style={{flex:1,minWidth:0}}><div style={{fontSize:12,fontWeight:track===t.name?700:500,color:track===t.name?C.red:C.text,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{t.name}{t.sprint?" ★":""}</div><div style={{fontSize:9,color:C.dim}}>R{t.round}</div></div></button>))}</div></div></div>
          {/* Step 2: Mode */}
          {step>=2&&(<div style={{background:C.card,borderRadius:12,border:`1px solid ${step===2?C.red:C.border}`,overflow:"hidden"}}><div style={{background:C.card2,padding:"12px 14px",borderBottom:`1px solid ${C.border}`}}><SH n={2} title="게임 모드" done={!!mode&&step>2}/></div><div style={{padding:"12px 14px",display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>{[["equal","⚖️","이퀄","동일"],["nonequal","🏆","논이퀄","팀별 차이"]].map(([k,ic,l,d])=>(<button key={k} onClick={()=>sMode(k)} style={{padding:"14px 10px",borderRadius:10,cursor:"pointer",textAlign:"left",border:`1px solid ${mode===k?C.red:C.border}`,background:mode===k?"rgba(239,68,68,0.12)":C.card2}}><div style={{fontSize:20,marginBottom:4}}>{ic}</div><div style={{fontSize:13,fontWeight:600,color:mode===k?C.red:C.text}}>{l}</div><div style={{fontSize:10,color:C.muted,marginTop:2}}>{d}</div></button>))}</div></div>)}
          {/* Step 2.5: Team (nonequal) */}
          {step>=2.5&&isNE&&(<div style={{background:C.card,borderRadius:12,border:`1px solid ${step===2.5?C.red:C.border}`,overflow:"hidden"}}><div style={{background:C.card2,padding:"12px 14px",borderBottom:`1px solid ${C.border}`}}><SH n={3} title="팀 선택" done={!!team&&step>2.5}/></div><div style={{padding:"12px 14px",display:"grid",gridTemplateColumns:"1fr 1fr",gap:6}}>{TEAMS.sort((a,b)=>b.total-a.total).map(t=>(<button key={t.name} onClick={()=>sTeam(t.name)} style={{padding:10,borderRadius:8,cursor:"pointer",textAlign:"left",border:`1px solid ${team===t.name?C.red:C.border}`,background:team===t.name?"rgba(239,68,68,0.12)":C.card2}}><div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}><span style={{fontSize:12,fontWeight:600,color:team===t.name?C.red:C.text}}>{t.name}</span><span style={{fontSize:10,fontWeight:700,color:"#f59e0b"}}>{t.total}pt</span></div></button>))}</div></div>)}
          {/* Step 3: Weather */}
          {step>=3&&(<div style={{background:C.card,borderRadius:12,border:`1px solid ${step===3?C.red:C.border}`,overflow:"hidden"}}><div style={{background:C.card2,padding:"12px 14px",borderBottom:`1px solid ${C.border}`}}><SH n={isNE?4:3} title="날씨" done={!!weather&&step>3}/></div><div style={{padding:"12px 14px",display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>{[["dry","☀️","건조","슬릭"],["rain","🌧️","우천","인터/웻"]].map(([k,ic,l,d])=>(<button key={k} onClick={()=>sW(k)} style={{padding:"14px 10px",borderRadius:10,cursor:"pointer",textAlign:"left",border:`1px solid ${weather===k?C.red:C.border}`,background:weather===k?"rgba(239,68,68,0.12)":C.card2}}><div style={{fontSize:22,marginBottom:4}}>{ic}</div><div style={{fontSize:13,fontWeight:600,color:weather===k?C.red:C.text}}>{l}</div><div style={{fontSize:10,color:C.muted,marginTop:2}}>{d}</div></button>))}</div></div>)}
          {/* Step 4: Setup list */}
          {step>=4&&(<div style={{background:C.card,borderRadius:12,border:`1px solid ${step===4?C.red:C.border}`,overflow:"hidden"}}>
            <div style={{background:C.card2,padding:"12px 14px",borderBottom:`1px solid ${C.border}`}}>
              <SH n={isNE?5:4} title="셋업 선택" done={!!selSetup&&step>4}/>
              {dd?.track&&(<div style={{background:"rgba(255,255,255,0.04)",borderRadius:8,padding:"8px 10px",marginBottom:10}}><p style={{fontSize:11,color:C.muted,margin:"0 0 6px"}}>{dd.track.notes}</p><div style={{display:"flex",gap:5,flexWrap:"wrap"}}>{[["S",dd.track.softLife,"#ef4444"],["M",dd.track.medLife,"#eab308"],["H",dd.track.hardLife,"#94a3b8"]].map(([l,v,c])=>(<span key={l} style={{fontSize:10,padding:"2px 7px",borderRadius:6,background:c+"18",color:c}}>{l} {v}</span>))}</div></div>)}
              {weather==="dry"&&(<div style={{display:"flex",gap:5,marginBottom:10,flexWrap:"wrap"}}>{[["all","전체"],["Istvan Puki","Puki"],["Brendon Leigh","BL"]].map(([k,l])=>(<button key={k} onClick={()=>setFg(k)} style={{padding:"4px 11px",borderRadius:20,border:`1px solid ${fg===k?C.red:C.border}`,background:fg===k?C.red:"transparent",color:fg===k?"#fff":C.muted,fontSize:11,cursor:"pointer"}}>{l}</button>))}</div>)}
            </div>
            <div style={{padding:"12px 14px"}}>{sortM.map(meta=>{const s=dd?.[getDbKey(meta)];if(!s)return null;const isExp=!!expanded[meta.key];const isSel=selMeta?.key===meta.key;const tags=gTags(s);const feel=gFeel(s);const cs=isNE&&ti?gCS(s,ti):null;const cl=cs!==null?gCL(cs):null;
              return(<div key={meta.key} style={{marginBottom:7,borderRadius:10,overflow:"hidden",border:`1px solid ${isSel?meta.color:C.border}`}}>
                <div onClick={()=>setExpanded(p=>({...p,[meta.key]:!p[meta.key]}))} style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",padding:"10px 12px",cursor:"pointer",background:C.card2}}>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:3}}><div style={{width:8,height:8,borderRadius:"50%",background:meta.color,flexShrink:0}}/><span style={{fontSize:12,fontWeight:700,color:isSel?meta.color:C.text}}>{meta.label}</span><span style={{fontSize:9,color:C.dim}}>{meta.who}</span></div>
                    {cl&&(<div style={{marginBottom:6,background:"rgba(0,0,0,0.2)",borderRadius:8,padding:"6px 8px"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:3}}><span style={{fontSize:10,fontWeight:600,color:cl.color}}>{cl.icon} {team} 궁합</span><span style={{fontSize:13,fontWeight:800,color:cl.color}}>{cs}</span></div><div style={{background:"rgba(255,255,255,0.07)",borderRadius:4,height:4,overflow:"hidden"}}><div style={{width:`${cs}%`,height:"100%",background:cl.color}}/></div><div style={{fontSize:9,color:cl.color,marginTop:2,fontWeight:600}}>{cl.label}</div></div>)}
                    <p style={{fontSize:10,color:"#a78bfa",margin:"0 0 4px",fontStyle:"italic"}}>💡 {feel}</p>
                    <div style={{display:"flex",flexWrap:"wrap",gap:4}}>{tags.map(tg=><span key={tg.label} style={{fontSize:9,padding:"2px 6px",borderRadius:4,background:tg.color+"18",color:tg.color}}>{tg.label}</span>)}</div>
                  </div>
                  <div style={{display:"flex",flexDirection:"column",alignItems:"flex-end",gap:5,marginLeft:8,flexShrink:0}}><button onClick={e=>{e.stopPropagation();sSt(meta,s);}} style={{fontSize:10,padding:"5px 11px",borderRadius:6,border:"none",background:meta.color,color:"#fff",cursor:"pointer",fontWeight:700}}>선택→</button><span style={{fontSize:10,color:C.dim}}>{isExp?"▲":"▼"}</span></div>
                </div>
                {isExp&&(<div style={{padding:"10px 12px",background:C.card,borderTop:`1px solid ${C.border}`}}><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"6px 12px"}}>{FIELDS.map(f=>(<div key={f.k}><div style={{display:"flex",justifyContent:"space-between",marginBottom:2}}><span style={{fontSize:9,color:C.dim}}>{f.l}</span><span style={{fontSize:10,fontWeight:600,color:C.text}}>{s[f.k]}</span></div><Bar v={s[f.k]} min={DEFS[f.k].min} max={DEFS[f.k].max}/></div>))}</div></div>)}
              </div>);})}</div>
          </div>)}
          {/* Step 5: AI Chat */}
          {step>=5&&selSetup&&(<div style={{background:C.card,borderRadius:12,border:`1px solid ${selMeta?.color||C.border}`,overflow:"hidden"}}>
            <div style={{background:C.card2,padding:"12px 14px",borderBottom:`1px solid ${C.border}`}}>
              <SH n={isNE?6:5} title="AI 피드백" done={false}/>
              <div style={{background:"rgba(255,255,255,0.04)",borderRadius:8,padding:"8px 10px"}}><p style={{fontSize:12,fontWeight:700,color:selMeta?.color,margin:0}}>{selMeta?.label}</p><p style={{fontSize:9,color:C.dim,margin:"2px 0 0"}}>{track}·{isNE?"논이퀄":"이퀄"}{team?`·${team}`:""}</p></div>
            </div>
            <div style={{padding:"12px 14px"}}>
              <div style={{minHeight:160,maxHeight:320,overflowY:"auto",display:"flex",flexDirection:"column",gap:8,marginBottom:8}}>
                {chat.length===0&&<div style={{textAlign:"center",color:C.dim,paddingTop:30,fontSize:11}}>💬 예시를 눌러보거나 입력하세요</div>}
                {chat.map((m,i)=>(<div key={i} style={{display:"flex",justifyContent:m.r==="u"?"flex-end":"flex-start"}}><div style={{maxWidth:"86%",padding:"8px 11px",fontSize:12,lineHeight:1.6,borderRadius:m.r==="u"?"12px 12px 3px 12px":"12px 12px 12px 3px",background:m.r==="u"?C.red:C.card2,border:m.r==="a"?`1px solid ${C.border}`:"none",color:C.text,whiteSpace:"pre-wrap"}}>{m.t}</div></div>))}
                {loading&&<div style={{display:"flex",justifyContent:"flex-start"}}><div style={{padding:"8px 12px",borderRadius:"12px 12px 12px 3px",fontSize:12,color:C.muted,background:C.card2}}>🔧 분석 중…</div></div>}
                <div ref={chatEnd}/>
              </div>
              <div style={{display:"flex",flexWrap:"wrap",gap:5,marginBottom:8}}>{qQ.map(q=>(<button key={q} onClick={()=>setInput(q)} style={{fontSize:10,padding:"4px 9px",borderRadius:12,cursor:"pointer",border:`1px solid ${C.border}`,background:C.card2,color:C.muted}}>{q}</button>))}</div>
              <div style={{display:"flex",gap:7}}><input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==="Enter"&&send()} placeholder="주행 느낌을 입력하세요…" style={{flex:1,padding:"9px 12px",borderRadius:8,border:`1px solid ${C.border2}`,background:C.card2,color:C.text,fontSize:12,outline:"none"}}/><button onClick={send} disabled={loading} style={{padding:"9px 16px",borderRadius:8,border:"none",background:loading?"#374151":C.red,color:"#fff",fontSize:12,fontWeight:700,cursor:loading?"not-allowed":"pointer"}}>전송</button></div>
            </div>
          </div>)}
        </div>)}

      </div>
    </div>
  );
}
